import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 collectAmount, address actor) public {
        // Restrict amounts to avoid overflow and ensure collect cannot exceed deposit
        depositAmount = bound(depositAmount, 1, type(uint128).max);
        collectAmount = bound(collectAmount, 1, type(uint128).max);
        vm.assume(actor != address(0));

        // Initialize contract: set MinSum to 0 and mark initialized
        c.SetMinSum(0);
        c.Initialized();

        // Record initial ether balance (should be 0)
        uint256 initialContractBalance = address(c).balance;

        // Fund actor and make a deposit
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.Deposit{value: depositAmount}();

        // Ensure collectAmount is not greater than the deposited balance for the actor
        vm.assume(collectAmount <= c.balances(actor));

        // Record total sum of all balances before Collect
        uint256 sumBalancesBefore = c.balances(actor);

        // Perform Collect
        vm.prank(actor);
        c.Collect(collectAmount);

        // After Collect, the sum of all balances should equal the contract's ether balance
        uint256 sumBalancesAfter = c.balances(actor);
        assertEq(sumBalancesAfter, address(c).balance - initialContractBalance);
    }
