contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmt, uint256 collectAmt) public {
        vm.assume(depositAmt > 0 && collectAmt > 0);
        address actor = address(this);
        // Initialize the contract and set a minimum sum that allows collecting
        vm.startPrank(actor);
        c.Initialized();
        c.SetMinSum(0);
        vm.stopPrank();

        // Record balance before any operation
        uint256 initialBalance = c.balances(actor);

        // Deposit funds
        vm.deal(actor, depositAmt);
        vm.prank(actor);
        c.Deposit{value: depositAmt}();

        // Collect a portion that does not exceed deposited amount
        vm.assume(collectAmt <= depositAmt);
        vm.prank(actor);
        try c.Collect(collectAmt) { } catch { }

        uint256 finalBalance = c.balances(actor);

        // After a single deposit of depositAmt and a successful collect of collectAmt,
        // the correct contract must have finalBalance = initialBalance + depositAmt - collectAmt.
