pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 collectAmount) public {
        // Keep amounts reasonable and collectAmount > 0 to trigger Collect path
        vm.assume(depositAmount > 0 && depositAmount < type(uint128).max);
        vm.assume(collectAmount > 0 && collectAmount <= depositAmount);

        address caller = address(0xB0B);
        vm.deal(caller, depositAmount);

        // Initialize contract and set MinSum to allow Collect
        c.Initialized();
        c.SetMinSum(0);

        // Deposit from caller
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Total ether received should equal depositAmount
        uint256 contractBalanceBefore = address(c).balance;
        // caller's balance in mapping
        uint256 userBalBefore = c.balances(caller);
        // fixed address balance (the bug writes here)
        uint256 fixedBalBefore = c.balances(address(0));

        vm.prank(caller);
        c.Collect(collectAmount);

        uint256 contractBalanceAfter = address(c).balance;
        uint256 userBalAfter = c.balances(caller);
        uint256 fixedBalAfter = c.balances(address(0));

        // In the correct contract, user balance decreases by exactly collectAmount,
        // fixed address balance never changes (unless someone sent Ether to address(0) directly via Deposit, which caller did not),
        // and contract balance decreases by collectAmount.
        // In the buggy contract, the deposit increments address(0) instead of caller,
        // so caller will have insufficient balance, causing Collect to either revert or underflow.
        // We enforce a universal invariant: after Collect, if the call succeeded (no revert),
        // then user balance must be exactly userBalBefore - collectAmount, and fixed address balance unchanged.
        // The bug can cause a revert or a state mismatch.
        // Wrap Collect in try/catch to observe revert.
        vm.prank(caller);
        try c.Collect(collectAmount) returns (bool) {
            // If no revert, universal rule: user balance decreased by collectAmount
            // and fixed address balance unchanged.
            assertTrue(userBalBefore - collectAmount == userBalAfter && fixedBalAfter == fixedBalBefore);
        } catch {
            // Revert also acceptable in reference for insufficient balance (bug may cause unexpected revert)
            assertTrue(true);
        }
    }
}

