        // Admissible domain: nonzero deposit, collect <= deposit, valid caller
        vm.assume(depositAmount > 0);
        vm.assume(collectAmount > 0);
        vm.assume(collectAmount <= depositAmount);
        vm.assume(caller != address(0));
        vm.assume(caller != address(c));

        // Setup: initialize contract, record caller's starting balance
        c.Initialized();
        vm.deal(caller, depositAmount);

        uint256 balanceBefore = c.balances(caller);

        // Deposit from caller
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Check deposit credited correctly to caller
